    ("wp47_generated_bundle_staleness.py", "# -*- coding: utf-8 -*-\n\"\"\"Exercise the opt-in land gate through the public CLI.\"\"\"\n\nimport contextlib\nimport io\nimport json\nfrom pathlib import Path\nimport tempfile\n\n\nTEST_ID = \"wp47_generated_bundle_staleness\"\n\n\n_FRAGMENT_SOURCE = (\n    b'TEST_ID = \"wp47_fixture\"\\n\\n\\n'\n    b'def run(tl_module):\\n'\n    b'    return True\\n'\n)\n_BUNDLED_SOURCE = (\n    b'# -*- coding: utf-8 -*-\\n'\n    b'\"\"\"Generated by tl_core.test_fragments; do not edit.\"\"\"\\n\\n'\n    b'BUNDLED_FRAGMENT_SOURCES = (\\n'\n    b'    (\"wp47_fixture.py\", \"TEST_ID = \\\\\"wp47_fixture\\\\\"\\\\n\\\\n\\\\ndef run(tl_module):\\\\n    return True\\\\n\"),\\n'\n    b')\\n'\n)\n\n\ndef _invoke(tl_module, root):\n    stdout = io.StringIO()\n    with contextlib.redirect_stdout(stdout):\n        try:\n            rc = tl_module.main([\n                \"test-fragments-check\", \"--root\", str(root), \"--json\"])\n        except SystemExit as exc:\n            rc = int(exc.code or 0)\n    try:\n        payload = json.loads(stdout.getvalue())\n    except (TypeError, ValueError):\n        payload = {}\n    return rc, payload\n\n\ndef run(tl_module):\n    with tempfile.TemporaryDirectory(prefix=\"wp47_bundle_check_\") as temp:\n        root = Path(temp)\n        scripts = root / \"scripts\"\n        fragments = scripts / \"test_fragments\"\n        fragments.mkdir(parents=True)\n        (fragments / \"wp47_fixture.py\").write_bytes(_FRAGMENT_SOURCE)\n        bundled = scripts / \"tl_test_fragments_bundled.py\"\n        bundled.write_bytes(_BUNDLED_SOURCE)\n\n        current_rc, current = _invoke(tl_module, root)\n        bundled.write_bytes(b\"stale\\n\")\n        stale_rc, stale = _invoke(tl_module, root)\n        bundled.unlink()\n        missing_rc, missing = _invoke(tl_module, root)\n\n    return (\n        current_rc == 0\n        and current.get(\"ok\") is True\n        and current.get(\"status\") == \"current\"\n        and stale_rc != 0\n        and stale.get(\"error\") == \"GENERATED_BUNDLE_STALE\"\n        and missing_rc != 0\n        and missing.get(\"error\") == \"BUNDLED_MODULE_MISSING\"\n    )\n"),
    ("wp49_eol_policy_index_blobs.py", "# -*- coding: utf-8 -*-\n\"\"\"F2-A (ADR-0018) — regression EOL canonical chạy TRONG canonical selftest.\n\nPHÂN CÔNG CÓ CHỦ ĐÍCH giữa hai suite, không phải trùng lặp lười:\n\n- Fragment NÀY chạy trong `tl --selftest` ở CẢ cây dev lẫn gói đã giải nén. Writer canonical,\n  `.gitattributes` và các bảng extension runtime đều có trong cả hai topology; `.editorconfig`\n  là config dev-side nên CỐ Ý bị release loại. Fragment phân biệt topology bằng chính source\n  fragment/bundled adapter, vì vậy bundle không biến thành ca rỗng chỉ vì thiếu config dev-side.\n- Nó KHÔNG import `.githooks/eol_policy.py` — `.githooks/` bị `_RELEASE_EXCLUDE_DIRS` loại khỏi\n  gói. `.githooks/eol_policy_test.py` dựng bundle thật, giải nén và chạy chính case `wp49` từ\n  generated adapter để khoá đường package này.\n- `.githooks/eol_policy_test.py` giữ phần hành vi validator ở tầng git (rename/copy, tên Unicode,\n  binary, tệp mới). Nó cần một kho git thật nên không package-safe; CI gọi nó CHẶN trên cả\n  ubuntu lẫn windows.\n\nVì sao cần ca trong canonical selftest: `.gitattributes` một mình KHÔNG chặn được artifact phái\nsinh. Tệp phái sinh được GHI RA trước, git chỉ nhìn thấy nó sau. Nếu writer nhả CRLF thì mỗi lần\ntái sinh golden/manifest lại đẻ một đợt renormalize, và F2 sẽ tự mở lại chính lớp hỏng nó vừa đóng.\n\"\"\"\nfrom __future__ import annotations\n\nimport re\nimport tempfile\nfrom pathlib import Path\n\nTEST_ID = \"wp49_eol_policy_index_blobs\"\n\n# Sàn chống RỖNG. Không phải bản sao của danh sách: nếu một nguồn hợp đồng bị đổi tên hay import\n# hỏng, tập suy ra co lại và phép `⊆` sẽ ĐÚNG một cách vô nghĩa. Sàn này biến \"vô tình rỗng\" thành\n# ĐỎ. Đo 07-08-2026: hợp nhất ba nguồn cho 12 họ.\n_SAN_TOI_THIEU = 10\n\n\ndef _root(tl_module):\n    \"\"\"Gốc kho/gói: `tl.py` luôn nằm ở `<root>/scripts/`, đúng ở cả cây dev lẫn bản giải nén.\"\"\"\n    return Path(tl_module.__file__).resolve().parent.parent\n\n\ndef _topology(tl_module):\n    \"\"\"Nhận diện tường minh dev/bundle; trạng thái lai hoặc thiếu adapter phải fail closed.\"\"\"\n    root = _root(tl_module)\n    source = root / \"scripts\" / \"test_fragments\" / \"wp49_eol_policy_index_blobs.py\"\n    bundled = root / \"scripts\" / \"tl_test_fragments_bundled.py\"\n    editorconfig = root / \".editorconfig\"\n    if source.is_file() and bundled.is_file() and editorconfig.is_file():\n        return \"dev\"\n    if not source.exists() and bundled.is_file() and not editorconfig.exists():\n        return \"bundle\"\n    return None\n\n\ndef _writer_canonical(tl_module):\n    \"\"\"Writer phải nhả LF dù đầu vào là CRLF, CR đơn lẻ hay trộn lẫn.\n\n    `newline=\"\\\\n\"` một mình KHÔNG đủ: nó tắt phép dịch `\\\\n`→`\\\\r\\\\n` lúc ghi nhưng không đụng\n    `\\\\r` đã nằm sẵn trong chuỗi. Đọc một tệp CRLF rồi ghi lại qua writer \"đã ghim LF\" vẫn ra CRLF.\n    \"\"\"\n    write = getattr(tl_module, \"_write_text_atomic\", None)\n    if not callable(write):\n        return False\n    mau = [\n        \"a\\r\\nb\\r\\n\",          # CRLF toàn phần\n        \"a\\r\\nb\\nc\\r\\n\",       # trộn\n        \"a\\rb\\r\",              # CR đơn lẻ (Mac cổ / stdout lạ)\n        \"a\\nb\\n\",              # vốn đã LF: phải giữ nguyên, không nhân đôi\n    ]\n    with tempfile.TemporaryDirectory(prefix=\"wp49_writer_\") as tmp:\n        for i, text in enumerate(mau):\n            # Ghi vào thư mục con CHƯA tồn tại: khoá luôn hợp đồng mkdir của writer.\n            dest = Path(tmp) / (\"sub%d\" % i) / \"out.txt\"\n            write(dest, text)\n            raw = dest.read_bytes()\n            if b\"\\r\" in raw:\n                return False\n            if raw.decode(\"utf-8\") != text.replace(\"\\r\\n\", \"\\n\").replace(\"\\r\", \"\\n\"):\n                return False\n    return True\n\n\ndef _writer_van_nguyen_tu(tl_module):\n    \"\"\"Chuẩn hoá không được làm mất ngữ nghĩa nguyên tử: ghi đè xong không để lại tmp lảng vảng.\"\"\"\n    write = tl_module._write_text_atomic\n    with tempfile.TemporaryDirectory(prefix=\"wp49_atomic_\") as tmp:\n        dest = Path(tmp) / \"out.txt\"\n        write(dest, \"cu\\r\\n\")\n        write(dest, \"moi\\r\\n\")\n        if dest.read_bytes() != b\"moi\\n\":\n            return False\n        # `mkstemp` cùng thư mục + `os.replace` ⇒ sau khi xong chỉ còn ĐÚNG tệp đích.\n        return sorted(p.name for p in Path(tmp).iterdir()) == [\"out.txt\"]\n\n\ndef _ho_binary_suy_ra(tl_module):\n    \"\"\"SUY RA họ binary từ bảng extension ingest/loader của kho, KHÔNG chép tay.\n\n    Một danh sách chép tay có khuyết điểm đi thẳng vào cả policy lẫn test, rồi hai bên gật đầu\n    với nhau — đúng cái bẫy đã để lọt `.xls/.odt/.tif/.tiff` ở vòng trước. Neo vào hợp đồng thật:\n\n      PROFILE_INGEST_ALLOWED_EXTS  tl.py                     allowlist của `profile-ingest`\n      INGEST_LOCAL_EXTS            tl_core/ingest_contract   allowlist của `ingest-local`\n      OCR_SOURCE_EXTS              tl_core/ingest_contract   nguồn đi đường OCR (ảnh + PDF)\n      _MIME_BY_EXT                 tl.py                     để loại `text/*` khỏi hợp nhất\n\n    Mở thêm một đuôi ở bất kỳ allowlist nào mà quên khai `-text` ⇒ ca này ĐỎ.\n    \"\"\"\n    from tl_core.ingest_contract import INGEST_LOCAL_EXTS, OCR_SOURCE_EXTS\n    nguon = [set(tl_module.PROFILE_INGEST_ALLOWED_EXTS), set(INGEST_LOCAL_EXTS), set(OCR_SOURCE_EXTS)]\n    if not all(nguon):                      # nguồn rỗng ⇒ phép ⊆ sẽ đúng vô nghĩa\n        return None\n    mime = getattr(tl_module, \"_MIME_BY_EXT\", None)\n    if not mime:\n        return None\n    hop = set().union(*nguon)\n    return {e for e in hop if not str(mime.get(e, \"\")).startswith(\"text/\")}\n\n\ndef _policy_khai_du(tl_module):\n    \"\"\"`.gitattributes` phải khai ĐỦ policy ADR-0018 và ĐỦ mọi họ binary suy ra được.\"\"\"\n    path = _root(tl_module) / \".gitattributes\"\n    if not path.is_file():\n        return False\n    noi_dung = path.read_text(encoding=\"utf-8\")\n    dong = [d.strip() for d in noi_dung.splitlines()]\n    dong = [d for d in dong if d and not d.startswith(\"#\")]\n    can = [\n        \"* text=auto eol=lf\",\n        \"*.cmd text eol=crlf\",\n        \"*.bat text eol=crlf\",\n        \"references/golden/** -text\",\n    ]\n    if any(c not in dong for c in can):\n        return False\n    # `* -text` cũ phải BIẾN MẤT: còn nó thì policy mới vô hiệu ngay từ dòng đầu.\n    if \"* -text\" in dong:\n        return False\n\n    suy_ra = _ho_binary_suy_ra(tl_module)\n    if not suy_ra or len(suy_ra) < _SAN_TOI_THIEU:\n        return False\n    khai = {m.group(1) for m in re.finditer(r\"(?m)^\\*(\\.[A-Za-z0-9]+) -text\\s*$\", noi_dung)}\n    return suy_ra <= khai\n\n\ndef _editorconfig_dong_bo(tl_module):\n    \"\"\"Ở topology dev, `.editorconfig` phải phủ những họ mà `.gitattributes` khai `-text`.\n\n    Hai tệp cưỡng chế cùng một policy ở hai tầng khác nhau (git vs editor). Chúng SẼ trôi lệch,\n    và bên quên cập nhật chính là bên để editor ghi lại CRLF vào một tệp đáng ra bất khả xâm phạm.\n    Gói release không ship config editor; `_topology()` xác nhận sự vắng mặt đó là cấu trúc bundle\n    thật, không phải một tệp dev vô tình mất rồi bị bỏ qua.\n    \"\"\"\n    root = _root(tl_module)\n    ec = root / \".editorconfig\"\n    if not ec.is_file():\n        return False\n    suy_ra = _ho_binary_suy_ra(tl_module)\n    if not suy_ra or len(suy_ra) < _SAN_TOI_THIEU:\n        return False\n    phu = set()\n    for m in re.finditer(r\"(?m)^\\[\\*\\.\\{([^}]*)\\}\\]\\s*$\", ec.read_text(encoding=\"utf-8\")):\n        phu |= {\".\" + x.strip() for x in m.group(1).split(\",\") if x.strip()}\n    return suy_ra <= phu\n\n\ndef run(tl_module):\n    topology = _topology(tl_module)\n    return bool(\n        topology\n        and _writer_canonical(tl_module)\n        and _writer_van_nguyen_tu(tl_module)\n        and _policy_khai_du(tl_module)\n        and (topology == \"bundle\" or _editorconfig_dong_bo(tl_module))\n    )\n"),
    ("wp725_huong_dan_nlm.py", "# -*- coding: utf-8 -*-\n\"\"\"wp725 — hướng dẫn NLM cũ (`nlm login --check` làm phép xác nhận) không quay lại tài liệu và help.\n\nN1: mọi dòng chứa `login --check` trong tài liệu Cowork Project / RUNBOOK.md phải khớp ĐÚNG MỘT neo trong danh sách\nCHO PHÉP (câu phủ định có chủ đích), và mỗi neo khớp đúng một dòng. N2: help của `nlm-auth-stage` và các cờ của nó\nkhông dạy quy trình cũ; help `--force` nói đúng là KHÔNG qua được cổng canary.\n\"\"\"\n\nimport argparse\nfrom pathlib import Path\n\n\nTEST_ID = \"wp725_huong_dan_nlm\"\n\n# Tên ghép từng mảnh CÓ CHỦ ĐÍCH: bundled module là `scripts/*.py`, mà doc-claims L9 đếm mọi tên tài liệu trong đó là\n# con trỏ SỐNG — viết trọn tên ở đây thì ca r228 (tài liệu mồ côi) tự xanh oan (cross-review wp725 lượt 2, F03).\n_COWORK = \"references/\" + \"COWORK_\" + \"PROJECT\" + \".md\"\n\n_CAU_CU = \"login --check\"\n\n# Danh sách CHO PHÉP: (tệp, chuỗi con neo duy nhất của dòng được phép nhắc `login --check`).\n_CHO_PHEP = (\n    (\"references/RUNBOOK.md\", \"`nlm login --check` xanh KHÔNG đủ.\"),\n    (\"references/RUNBOOK.md\", \"`nlm login --check` KHÔNG còn là bằng chứng\"),\n    (\"references/RUNBOOK.md\", \"rc 0 của refresh, `nlm login --check` hay số notebook đều KHÔNG cho phép upload\"),\n    (_COWORK, \"`nlm login --check` xanh hay rc 0 của refresh KHÔNG đủ để stage\"),\n)\n\n\ndef _vi_pham_tai_lieu(van_ban_theo_tep):\n    \"\"\"Trả danh sách vi phạm (rỗng = đạt). `van_ban_theo_tep`: {đường dẫn tương đối: văn bản}.\"\"\"\n    loi = []\n    dung = {neo: 0 for neo in _CHO_PHEP}\n    for tep, van_ban in van_ban_theo_tep.items():\n        for so, dong in enumerate(van_ban.splitlines(), 1):\n            if _CAU_CU not in dong:\n                continue\n            khop = [neo for neo in _CHO_PHEP if neo[0] == tep and neo[1] in dong]\n            if len(khop) != 1:\n                loi.append(f\"{tep}:{so}\")\n            for neo in khop:\n                dung[neo] += 1\n    loi.extend(f\"neo:{neo[0]}:{neo[1][:30]}={n}\" for neo, n in dung.items() if n != 1)\n    return loi\n\n\n_KEO_CU = (\"- **Drive → Cowork (kéo):** đầu phiên `bootstrap` đã ghi cookie; giữa phiên cần mới hơn thì\\n\"\n           \"  `python scripts/tl.py nlm-auth-pull --secrets-file ./tl_secrets.enc` (hoặc bỏ `--secrets-file` để direct-media\\n\"\n           \"  kéo bản mới nhất trên Drive). Cowork KHÔNG tự chạy browser được nên KHÔNG tự refresh — refresh thật ở Code.\\n\")\n\n\ndef _vi_pham_duong_keo(cowork):\n    \"\"\"Bước 3: bản wrapper đẩy ở NLM_CRED_FILEID ⇒ đường kéo mặc định phải là `nlm-auth-load`, không phải\n    `nlm-auth-pull` (đọc bundle `secrets`, cũ hơn) — reviewer lượt 1 đo được pull nhận bản CŨ, rc 0.\"\"\"\n    try:\n        buoc3 = cowork.split(\"## Bước 3\", 1)[1].split(\"\\n## \", 1)[0]\n        keo = buoc3.split(\"- **Drive → Cowork (kéo):**\", 1)[1].split(\"\\n\\n\", 1)[0].split(\"\\n- **\", 1)[0]\n    except IndexError:\n        return [\"thiếu Bước 3 / mục kéo\"]\n    loi = []\n    if \"nlm-auth-load\" not in keo:\n        loi.append(\"mục kéo không nêu nlm-auth-load\")\n    elif \"nlm-auth-pull\" in keo and keo.index(\"nlm-auth-pull\") < keo.index(\"nlm-auth-load\"):\n        loi.append(\"nlm-auth-pull đứng trước nlm-auth-load\")\n    if \"nlm-auth-pull --secrets-file\" in keo:\n        loi.append(\"mục kéo còn dạy nlm-auth-pull --secrets-file làm đường mặc định\")\n    # Khối Project Instructions (Bước 2) là thứ người dùng DÁN vào Project — lượt 2 F02: nó vẫn dạy pull bundle.\n    for so, dong in enumerate(cowork.splitlines(), 1):\n        if \"refresh cookie giữa phiên\" in dong and \"nlm-auth-load\" not in dong:\n            loi.append(f\"dòng {so}: lệnh refresh giữa phiên không phải nlm-auth-load\")\n    if \"nlm-auth-pull --secrets-file\" in cowork:\n        loi.append(\"tài liệu còn lệnh nlm-auth-pull --secrets-file\")\n    return loi\n\n\ndef _help_nlm_auth_stage(tl_module):\n    parser = tl_module.build_parser()\n    sub = next(a for a in parser._actions if isinstance(a, argparse._SubParsersAction))\n    cmd = sub.choices[\"nlm-auth-stage\"]\n    lenh_help = next(c.help for c in sub._choices_actions if c.dest == \"nlm-auth-stage\")\n    co = {s: a.help or \"\" for a in cmd._actions for s in a.option_strings}\n    return lenh_help or \"\", co\n\n\ndef _vi_pham_help(lenh_help, co):\n    loi = []\n    tat_ca = [lenh_help, co.get(\"--refresh\", \"\"), co.get(\"--force\", \"\")]\n    if any(_CAU_CU in h for h in tat_ca):\n        loi.append(\"help nhắc login --check\")\n    if \"sau `nlm login`\" in lenh_help:\n        loi.append(\"help lệnh: stage sau nlm login\")\n    if \"canary\" not in lenh_help:\n        loi.append(\"help lệnh: thiếu cổng canary\")\n    force = co.get(\"--force\", \"\")\n    if \"bỏ qua cổng verify\" in force or \"DÙ cookie đang chết\" in force:\n        loi.append(\"help --force: hứa bỏ qua cổng\")\n    if \"KHÔNG bỏ qua được cổng canary\" not in force:\n        loi.append(\"help --force: thiếu khẳng định cổng vẫn áp\")\n    if \"tái sinh cookie từ browser profile\" in co.get(\"--refresh\", \"\"):\n        loi.append(\"help --refresh: mô tả cơ chế cũ\")\n    return loi\n\n\ndef run(tl_module):\n    goc = Path(tl_module.__file__).resolve().parent.parent\n    tai_lieu = {t: (goc / t).read_text(encoding=\"utf-8\")\n                for t in (\"references/RUNBOOK.md\", _COWORK)}\n    if _vi_pham_tai_lieu(tai_lieu):\n        return False\n    # Phản chứng tại chỗ: một dòng khẳng định kiểu cũ bơm vào phải bị bắt — chứng minh bộ kiểm có răng.\n    ban_ban = dict(tai_lieu)\n    ban_ban[_COWORK] += \"\\nĐịnh kỳ chạy `tl secrets-set --nlm` (tự `nlm login --check` refresh).\\n\"\n    if not _vi_pham_tai_lieu(ban_ban):\n        return False\n    cowork = tai_lieu[_COWORK]\n    if _vi_pham_duong_keo(cowork):\n        return False\n    keo_moi = cowork.split(\"- **Drive → Cowork (kéo):**\", 1)[1].split(\"\\n\\n\", 1)[0]\n    if not _vi_pham_duong_keo(cowork.replace(\"- **Drive → Cowork (kéo):**\" + keo_moi + \"\\n\", _KEO_CU, 1)):\n        return False            # phản chứng: trả mục kéo về bản cũ (pull bundle) phải bị bắt\n    lenh_moi = \"python scripts/tl_boot.py nlm-auth-load\"\n    if not _vi_pham_duong_keo(cowork.replace(lenh_moi, \"python scripts/tl_boot.py nlm-auth-pull --secrets-file ./tl_secrets.enc\", 1)):\n        return False            # phản chứng: trả RIÊNG dòng refresh của Project Instructions về pull bundle phải bị bắt\n    lenh_help, co = _help_nlm_auth_stage(tl_module)\n    if _vi_pham_help(lenh_help, co):\n        return False\n    co_cu = dict(co)\n    co_cu[\"--force\"] = \"(v1.33.39) bỏ qua cổng verify-LIVE — ép stage DÙ cookie đang chết\"\n    return bool(_vi_pham_help(lenh_help, co_cu))\n"),
    ("wp726_script_nlm_canary.py", "# -*- coding: utf-8 -*-\n\"\"\"wp726 — ba script shell NLM phán sống/chết bằng canary, không bằng `nlm login --check`, không nuốt mã thoát.\n\nChạy BẢN THẬT của `nlm-auto-refresh.sh`, `env-reimport.sh`, `nlm-auth-import.sh` bằng `bash` với `TL_ROOT` trỏ\nmột gốc giả: `scripts/tl.py` giả (vừa là module cho probe canary, vừa là CLI), `nlm`/`gws` giả trên PATH. Đồ giả\nGIỮ TRẠNG THÁI qua một tệp JSON — `nlm login --check` LUÔN báo \"valid\" (false-green), còn canary và mã của\n`nlm-auth-stage` là hai biến độc lập — và ghi nhật ký mọi lời gọi. Mọi đồ giả in một chuỗi canh; đầu ra của\nscript không được chứa nó.\n\"\"\"\n\nimport importlib.util\nimport json\nimport os\nfrom pathlib import Path\nimport shutil\nimport subprocess\nimport sys\nimport tempfile\n\n\nTEST_ID = \"wp726_script_nlm_canary\"\n\n_CANH = \"SENTINEL-COOKIE-wp726\"\n\n_TL_GIA = r'''\nimport json, os, sys\n_ST = os.environ[\"WP726_STATE\"]\n_LOG = os.environ[\"WP726_LOG\"]\nNLM_CRED_FILEID = \"FAKE-NLM-CRED\"\n\ndef _ghi(dong):\n    with open(_LOG, \"a\", encoding=\"utf-8\") as f:\n        f.write(dong + \"\\n\")\n\ndef _trang_thai():\n    with open(_ST, encoding=\"utf-8\") as f:\n        return json.load(f)\n\ndef _imp(name):\n    return sys.modules[__name__]\n\ndef bind(_m):\n    return None\n\ndef _nlm_canary_notebook(nb):\n    return \"NB-OFFLINE\"\n\ndef _nlm_auth_alive(nb, require_notebook_body=False):\n    _ghi(\"canary require_body=%s\" % require_notebook_body)\n    print(\"%s canary\" % os.environ.get(\"WP726_CANH\", \"\"))\n    if not require_notebook_body:\n        return True, \"rc0-only\"          # probe lỏng = false-green: chỉ phép đo đòi THÂN mới thấy canary thật\n    return _trang_thai()[\"canary\"], \"OFFLINE\"\n\nif __name__ == \"__main__\":\n    lenh = sys.argv[1] if len(sys.argv) > 1 else \"\"\n    _ghi(\"tl \" + \" \".join(sys.argv[1:]))\n    print(\"%s tl %s\" % (os.environ.get(\"WP726_CANH\", \"\"), lenh))\n    print(\"%s\" % os.environ.get(\"WP726_CANH\", \"\"), file=sys.stderr)\n    if lenh == \"ping\":\n        print('{\"ok\": true, \"version\": \"offline\"}')\n    elif lenh == \"nlm-auth-stage\":\n        st = _trang_thai()\n        day = st.get(\"stage_seq\")          # chuỗi mã theo thứ tự gọi (vd. 5 rồi 0) — trạng thái, không kịch bản\n        if day:\n            st[\"stage_seq\"] = day[1:] or day\n            with open(_ST, \"w\", encoding=\"utf-8\") as f:\n                json.dump(st, f)\n            sys.exit(day[0])\n        sys.exit(st[\"stage_rc\"])\n    elif lenh == \"nlm-auth-load\":\n        sys.exit(_trang_thai().get(\"load_rc\", 0))\n    elif lenh == \"doctor\":                  # dạng dòng THẬT của doctor: nhãn — chi tiết (chi tiết có thể mang lỗi thô)\n        canh = os.environ.get(\"WP726_CANH\", \"\")\n        print(\"✓ nlm auth (LIVE probe) — PROBE_INCONCLUSIVE (không phải auth): \" + canh)\n        print(\"⚠ gws credential — \" + canh)\n    sys.exit(0)\n'''\n\n_CONVERT_GIA = r'''\nimport pathlib, sys\npathlib.Path(sys.argv[2]).mkdir(parents=True, exist_ok=True)\n(pathlib.Path(sys.argv[2]) / \"cookies.json\").write_text(\"[]\", encoding=\"utf-8\")\n'''\n\n_NLM_GIA = '''#!/usr/bin/env bash\necho \"nlm $*\" >> \"$WP726_LOG\"\necho \"$WP726_CANH\"\ncase \"$1 $2\" in\n  \"login --check\") echo \"Authentication valid. Notebooks found: 7\"; exit 0 ;;\nesac\nexit 0\n'''\n\n_GWS_GIA = r'''\nimport json, os, sys\na = sys.argv[1:]\nwith open(os.environ[\"WP726_LOG\"], \"a\", encoding=\"utf-8\") as f:\n    f.write(\"gws \" + \" \".join(a) + \"\\n\")\nwith open(os.environ[\"WP726_STATE\"], encoding=\"utf-8\") as f:\n    st = json.load(f)\nlenh = \" \".join(a[:3])\nif lenh == \"drive files list\":\n    tep = [{\"id\": \"EXPORT-1\", \"name\": \"nlm-auth-x.json\", \"modifiedTime\": \"2026-10-01T00:00:00Z\"}] if st.get(\"export\") else []\n    print(json.dumps({\"files\": tep}))\nelif lenh == \"drive files get\":\n    if \"--output\" in a:\n        with open(a[a.index(\"--output\") + 1], \"w\", encoding=\"utf-8\") as f:\n            f.write('[{\"name\": \"SID\", \"value\": \"x\", \"domain\": \".google.com\"}]')\n    else:\n        print(\"{}\")\n'''\n\n\ndef _dung_goc(tam, kho):\n    goc = tam / \"goc\"\n    (goc / \"scripts\").mkdir(parents=True)\n    (goc / \"scripts\" / \"tl.py\").write_text(_TL_GIA, encoding=\"utf-8\")\n    (goc / \"scripts\" / \"nlm_auth_convert.py\").write_text(_CONVERT_GIA, encoding=\"utf-8\")\n    bin_ = tam / \"bin\"\n    bin_.mkdir()\n    for ten, noi_dung in ((\"nlm\", _NLM_GIA), (\"gws\", \"#!\" + sys.executable + \"\\n\" + _GWS_GIA)):\n        p = bin_ / ten\n        p.write_text(noi_dung, encoding=\"utf-8\")\n        p.chmod(0o755)\n    # `nlm-auto-refresh.sh` gọi `./scripts/nlm-auth-import.sh` TƯƠNG ĐỐI gốc ⇒ đặt BẢN THẬT vào gốc giả.\n    shutil.copy2(kho / \"scripts\" / \"nlm-auth-import.sh\", goc / \"scripts\" / \"nlm-auth-import.sh\")\n    (tam / \"home\").mkdir()\n    cookie = tam / \"cookie.json\"\n    cookie.write_text('[{\"name\": \"SID\", \"value\": \"x\", \"domain\": \".google.com\"}]', encoding=\"utf-8\")\n    return goc, bin_, cookie\n\n\ndef _bin_khong_nlm(tam, bin_):\n    \"\"\"Thư mục bin chỉ có `gws` giả — dựng ca THIẾU nlm (lượt review 2, F6).\"\"\"\n    b = tam / \"bin_khong_nlm\"\n    if not b.exists():\n        b.mkdir()\n        shutil.copy2(bin_ / \"gws\", b / \"gws\")\n    return b\n\n\ndef _chay(bash, kho, tam, goc, bin_, script, args, trang_thai):\n    st = tam / \"state.json\"\n    log = tam / \"calls.log\"\n    st.write_text(json.dumps(trang_thai), encoding=\"utf-8\")\n    log.write_text(\"\", encoding=\"utf-8\")\n    env = {\n        \"PATH\": (f\"{_bin_khong_nlm(tam, bin_)}{os.pathsep}{os.path.dirname(sys.executable)}{os.pathsep}/usr/bin:/bin\"\n                 if trang_thai.get(\"khong_nlm\") else f\"{bin_}{os.pathsep}{os.environ.get('PATH', '')}\"),\n        \"HOME\": str(tam / \"home\"),\n        \"TL_ROOT\": str(goc),\n        \"TL_PYTHON\": sys.executable,\n        \"TL_TOKEN\": \"offline-test-token\",\n        \"WP726_STATE\": str(st),\n        \"WP726_LOG\": str(log),\n        \"WP726_CANH\": _CANH,\n        \"PYTHONDONTWRITEBYTECODE\": \"1\",\n    }\n    r = subprocess.run([bash, str(kho / \"scripts\" / script), *args], env=env, cwd=str(goc),\n                       capture_output=True, text=True, timeout=120)\n    return r.returncode, r.stdout + r.stderr, log.read_text(encoding=\"utf-8\").splitlines()\n\n\ndef _sach(out, calls):\n    \"\"\"Không lộ chuỗi canh, không có lời gọi `nlm login --check`.\"\"\"\n    return _CANH not in out and not any(c.startswith(\"nlm login --check\") for c in calls)\n\n\ndef _ca(bash, kho):\n    kq = {}\n    with tempfile.TemporaryDirectory(prefix=\"wp726_\") as td:\n        tam = Path(td)\n        goc, bin_, cookie = _dung_goc(tam, kho)\n\n        def chay(script, args, canary, stage_rc, **them):\n            return _chay(bash, kho, tam, goc, bin_, script, args, {\"canary\": canary, \"stage_rc\": stage_rc, **them})\n\n        # nlm-auto-refresh.sh — phán quyết = mã của nlm-auth-stage; rc 4 hỏi lại canary: chỉ ÂM mới là chết (3),\n        # không kết luận / lệch nhau là 2 (GitHub review #730, P2)\n        for ten, canary, stage_rc, ma in ((\"tu_dong_song\", None, 0, 0), (\"tu_dong_chet\", False, 4, 3),\n                                          (\"tu_dong_khong_ro\", None, 4, 2), (\"tu_dong_lech\", True, 4, 2),\n                                          (\"tu_dong_ha_tang\", False, 5, 2)):\n            rc, out, calls = chay(\"nlm-auto-refresh.sh\", [], canary, stage_rc)\n            n_stage = sum(1 for c in calls if c == \"tl nlm-auth-stage\")\n            kq[ten] = rc == ma and n_stage == 1 and (\"NLM CHẾT\" in out) == (ma == 3) and _sach(out, calls)\n\n        # nlm-auto-refresh.sh — có export MỚI: import (canary + stage) rồi KHÔNG stage lần hai; chỉ xoá plaintext\n        # khi import+stage thành công (lượt review 1, F2)\n        # Import hỏng ⇒ thoát 2, KHÔNG stage lần hai, KHÔNG xoá, không báo sống — kể cả stage 5 rồi 0 (review #730, P1)\n        for ten, canary, stage, ma, can_stage, can_xoa in ((\"tu_dong_export_song\", True, 0, 0, 1, 1),\n                                                           (\"tu_dong_export_stage_loi\", True, 4, 2, 1, 0),\n                                                           (\"tu_dong_export_5_roi_0\", True, [5, 0], 2, 1, 0),\n                                                           (\"tu_dong_export_chet\", False, 0, 2, 0, 0)):\n            them = {\"stage_seq\": stage} if isinstance(stage, list) else {}\n            rc, out, calls = chay(\"nlm-auto-refresh.sh\", [], canary, 0 if them else stage, export=True, **them)\n            n_stage = sum(1 for c in calls if c == \"tl nlm-auth-stage\")\n            n_xoa = sum(1 for c in calls if c.startswith(\"gws drive files delete\"))\n            kq[ten] = (rc == ma and n_stage == can_stage and n_xoa == can_xoa and (\"bundle tươi)\" in out) == (ma == 0)\n                       and _sach(out, calls))\n\n        # env-reimport.sh — nlm-auth-load lỗi: chỉ báo mã, không in đầu ra lệnh (lượt review 1, F3)\n        rc, out, calls = chay(\"env-reimport.sh\", [], True, 0, load_rc=5)\n        kq[\"env_load_loi_khong_lo\"] = rc == 0 and \"nlm-auth-load lỗi (rc=5)\" in out and _sach(out, calls)\n\n        # env-reimport.sh — THIẾU nlm (có/không --check): không được báo \"đều sống\", rc 4, 0 canary (lượt 2, F6)\n        for ten, tham in ((\"env_thieu_nlm\", []), (\"env_thieu_nlm_check\", [\"--check\"])):\n            rc, out, calls = chay(\"env-reimport.sh\", tham, True, 0, khong_nlm=True)\n            kq[ten] = (rc == 4 and \"đều sống\" not in out\n                       and not any(c.startswith(\"canary\") for c in calls) and _sach(out, calls))\n\n        # env-reimport.sh — canary đòi thân đúng notebook\n        for ten, canary, ma in ((\"env_song\", True, 0), (\"env_chet\", False, 3), (\"env_khong_ro\", None, 4)):\n            rc, out, calls = chay(\"env-reimport.sh\", [], canary, 0)\n            kq[ten] = (rc == ma and \"canary require_body=True\" in calls\n                       and not any(c.startswith(\"tl nlm-auth-stage\") for c in calls) and _sach(out, calls))\n\n        # nlm-auth-import.sh — bước 4 canary, bước 5 phân biệt rc của stage\n        tham = [\"--file\", str(cookie)]\n        for ten, canary, stage_rc, ma, can_stage in (\n                (\"nhap_chet\", False, 0, 4, 0), (\"nhap_khong_ro\", None, 0, 6, 0), (\"nhap_song\", True, 0, 0, 1),\n                (\"nhap_stage_4\", True, 4, 5, 1), (\"nhap_stage_5\", True, 5, 5, 1)):\n            rc, out, calls = chay(\"nlm-auth-import.sh\", tham, canary, stage_rc)\n            n_stage = sum(1 for c in calls if c == \"tl nlm-auth-stage\")\n            kq[ten] = rc == ma and n_stage == can_stage and _sach(out, calls)\n            kq[ten + \"_out\"] = out\n    ok_4_5 = (\"canary của lệnh stage KHÔNG dương\" in kq.pop(\"nhap_stage_4_out\")\n              and \"lỗi stage\" in kq.pop(\"nhap_stage_5_out\"))\n    for k in [k for k in kq if k.endswith(\"_out\")]:\n        kq.pop(k)\n    kq[\"nhap_phan_biet_4_5\"] = ok_4_5\n    return kq\n\n\ndef _bash_nen(kho):\n    \"\"\"`ops/bash_nen.py` của kho (cổng cấm `bash` TRẦN — Issue #570). None khi cây không mang `ops/` (gói phát hành).\"\"\"\n    p = kho / \"ops\" / \"bash_nen.py\"\n    if not p.is_file():\n        return None\n    spec = importlib.util.spec_from_file_location(\"_wp726_bash_nen\", p)\n    mod = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(mod)\n    return mod\n\n\ndef run(tl_module):\n    kho = Path(tl_module.__file__).resolve().parent.parent\n    bash_nen = _bash_nen(kho)\n    if os.name != \"posix\" or bash_nen is None:\n        # Lệch có khai so với spec N6: API fragment chỉ có đúng/sai, không có trạng thái `skipped`. Nền không POSIX\n        # (Windows) và cây phát hành (không mang `ops/bash_nen.py`, bộ tìm bash DUY NHẤT được phép) không chạy ca\n        # này; ca trả True và in lý do — handoff khai riêng.\n        print(\"[wp726_script_nlm_canary] BỎ QUA (os.name=%s, ops/bash_nen.py %s)\"\n              % (os.name, \"có\" if bash_nen else \"vắng\"), file=sys.stderr)\n        return True\n    bash, _chan_doan = bash_nen.tim_bash()\n    if not bash:\n        return False                     # cây dev POSIX mà không có bash dùng được ⇒ ĐỎ, không tha\n    kq = _ca(bash, kho)\n    return bool(kq) and all(kq.values())\n"),
    ("wp727_tl_gws_refresh.py", "# -*- coding: utf-8 -*-\n\"\"\"wp727 — `_refresh_nlm_auth` gọi `nlm auth refresh` (không còn `nlm login --check`) và KHÔNG mở được cổng.\n\nN1 argv/timeout · N2 canary False/None ⇒ 0 upload rc 4 (kể cả --refresh --force), True ⇒ 1 upload; refresh quá hạn ⇒\nDỪNG · N3 lỗi refresh không lan · N4 `login --check` chỉ ở dòng/chuỗi CHO PHÉP (tĩnh, phụ) · N5 đầu ra THẬT của từng\nnhánh gợi ý WP727 sửa không gợi ý `login --check` và không lộ cookie.\n\"\"\"\n\nimport argparse\nimport ast\nimport contextlib\nimport hashlib\nimport io\nimport math\nimport os\nfrom pathlib import Path\nimport subprocess\nfrom unittest import mock\n\n\nTEST_ID = \"wp727_tl_gws_refresh\"\n\n_CHO_PHEP = (      # NGUYÊN VĂN từng dòng (đã strip) được phép nhắc `login --check` — so CẢ DÒNG, không chuỗi con\n    '\"\"\"M1 (v1.33.35 — log rà 45 Luật LIVE: nlm-auth-load/doctor/`nlm login --check` báo XANH [rc=0] nhưng',\n    'server (`nlm notebook get` base notebook) thay vì tin tuổi file / `login --check` (không chứng minh cookie',\n    'WP727: thay `nlm login --check` (lệnh KIỂM, false-green — không phải lệnh làm tươi). Trả True khi lệnh rc 0;',\n    'print(f\"[nlm-auth-pull] ✓ nlm auth {len(nlm)} file → ~/.notebooklm-mcp-cli{agestr} [nguồn {src}]. Kiểm bằng probe LIVE (`tl nlm-auth-status`), KHÔNG bằng `nlm login --check`\"',\n    '# lặp stage-lại-vô-ích). VERIFY LIVE bằng canary notebook_get (KHÔNG tin `nlm login --check` — false-red).',\n    'print(f\"[nlm-auth-load] ✓ nạp nlm cookie → {msg} (chmod 600). nlm chạy headless. Kiểm bằng probe LIVE (`tl nlm-auth-status`), KHÔNG bằng `nlm login --check`\")',\n)\n\n\nclass _Ket:\n    def __init__(self, rc):\n        self.returncode = rc\n        self.stdout = \"SENTINEL-COOKIE-wp727\"\n        self.stderr = \"SENTINEL-COOKIE-wp727-err\"\n\n\n_va = mock.patch.multiple      # thay thuộc tính tạm, tự trả lại kể cả khi lỗi\n\n\ndef _goi_refresh(tg, hanh_vi):\n    nhat_ky = []\n\n    def run(argv, **kw):\n        nhat_ky.append((list(argv), kw))\n        return hanh_vi(argv, kw)\n    import shutil\n    ra, loi = io.StringIO(), io.StringIO()\n    with _va(subprocess, run=run), _va(shutil, which=lambda name: \"/fake/bin/nlm\"), \\\n            contextlib.redirect_stdout(ra), contextlib.redirect_stderr(loi):\n        try:\n            kq = tg._refresh_nlm_auth()\n        except Exception:  # noqa: BLE001 — lỗi lan ra khỏi refresh là VI PHẠM N3, đo thành giá trị riêng\n            kq = \"LAN_LOI\"\n    if ra.getvalue() or loi.getvalue():\n        kq = \"IN_DAU_RA\"        # helper không được in gì (đầu ra con có thể mang cookie)\n    return kq, nhat_ky\n\n\ndef _n1_n3(tg):\n    ok_true, log1 = _goi_refresh(tg, lambda a, k: _Ket(0))\n    ok_false, _ = _goi_refresh(tg, lambda a, k: _Ket(1))\n    if not (ok_true is True and ok_false is False and len(log1) == 1):\n        return False\n    argv, kw = log1[0]\n    timeout = kw.get(\"timeout\")\n    if (argv[1:] != [\"auth\", \"refresh\"] or {kw.get(\"stdout\"), kw.get(\"stderr\")} != {subprocess.DEVNULL} or isinstance(timeout, bool)\n            or not isinstance(timeout, (int, float)) or not math.isfinite(timeout) or timeout <= 0):\n        return False\n\n    def treo(a, k):\n        raise subprocess.TimeoutExpired(a, k.get(\"timeout\"))\n    def hong(a, k):\n        raise OSError(\"no exec\")\n    return _goi_refresh(tg, treo)[0] is None and _goi_refresh(tg, hong)[0] is False   # quá hạn ⇒ None: người gọi DỪNG\n\n\ndef _stage(tg, canary, refresh_rc=0, ket_qua_ra=None):\n    \"\"\"`nlm-auth-stage --refresh --force`, nlm giả, cookie 20 ngày; trả (rc, số upload, sự kiện); `ket_qua_ra` nhận đầu ra.\"\"\"\n    su_kien, upload = [], []\n    ra, loi = io.StringIO(), io.StringIO()\n\n    def run(argv, **kw):\n        su_kien.append(\"refresh\")\n        if refresh_rc == \"treo\":\n            raise subprocess.TimeoutExpired(argv, kw.get(\"timeout\"))\n        return _Ket(refresh_rc)\n    def alive(nb, **kw):\n        su_kien.append(\"canary\")\n        return canary, \"OFFLINE\"\n    import shutil\n    ns = argparse.Namespace(refresh=True, force=True, folder=None, cred_file_id=\"OFFLINE\", new=False,\n                            config=None, profile=None)\n    with mock.patch.dict(os.environ, {\"TL_TOKEN\": \"offline-test-token\"}), _va(subprocess, run=run), \\\n            _va(shutil, which=lambda name: \"/fake/bin/nlm\"), \\\n            _va(tg, _nlm_auth_alive=alive,\n                _nlm_auth_files=lambda: (su_kien.append(\"jar\") or {\"auth.json\": \"offline-jar\"}),\n                _stage_enc_upload=lambda *a, **k: (upload.append(1) or (\"OFFLINE\", True)),\n                _nlm_auth_age_days=lambda _nlm: 20.0), \\\n            contextlib.redirect_stdout(ra), contextlib.redirect_stderr(loi):\n        rc = tg.cmd_nlm_auth_stage(ns)\n    if ket_qua_ra is not None:\n        ket_qua_ra.append(ra.getvalue() + loi.getvalue())\n    return rc, len(upload), su_kien\n\n\ndef _n2(tg):\n    for canary in (False, None):\n        for refresh_rc in (0, 1):\n            rc, n_up, su_kien = _stage(tg, canary, refresh_rc)\n            if rc != 4 or n_up != 0 or su_kien[:1] != [\"refresh\"] or \"canary\" not in su_kien:\n                return False\n    rc, n_up, su_kien = _stage(tg, True, \"treo\")       # refresh quá hạn: cây con có thể còn ghi hồ sơ (review #731)\n    if rc != 2 or n_up != 0 or su_kien != [\"refresh\"]:\n        return False\n    dau_ra = []\n    rc, n_up, su_kien = _stage(tg, True, 0, dau_ra)\n    # ĐO ĐẦU RA THẬT (lượt 3, F2c): mọi cách dựng chuỗi đều hiện ra ở đây — không `login --check`, không lộ chuỗi canh.\n    ra = dau_ra[0]\n    return (rc == 0 and n_up == 1 and su_kien.index(\"refresh\") < su_kien.index(\"canary\")\n            and \"NGÀY tuổi\" in ra and \"login --check\" not in ra and \"SENTINEL-COOKIE\" not in ra)\n\n\ndef _n4(van_ban):\n    \"\"\"Mọi dòng nhắc `login --check` phải BẰNG NGUYÊN VĂN một dòng cho phép, mỗi dòng cho phép đúng một lần.\"\"\"\n    return sorted(d.strip() for d in van_ban.splitlines() if \"login --check\" in d) == sorted(_CHO_PHEP)\n\n\n# sha256 TOÀN VĂN mỗi chuỗi Python được phép chứa `login --check` (sau ghép literal / f-string / `+`; lượt 2, F2b).\n_CHUOI_CHO_PHEP = frozenset({\n    \"a4b85ff4f950bfb6229494d8dd99fbfdb412490ad5b2a190971e5cef343a7e05\",   # docstring _nlm_auth_alive (M1)\n    \"73818ecbc71850b0fd01b94be79d0eefb95ca7e78fd9adf941b4ae778bba6264\",   # docstring _refresh_nlm_auth (WP727)\n    \"bdb136eb46706b57fcf701c877904c9f27c0d1f9b7f0b3ed0ca0ee78d02eb0a9\",   # thông báo nlm-auth-pull\n    \"a2e363f715ec74d607f55eb2f4a3821d0f6eda93e0be5e654d8831fc9985d6b5\",   # thông báo nlm-auth-load\n})\n\n\ndef _phan_f(v):\n    \"\"\"Mảnh f-string: hằng giữ nguyên; `{hằng}` trần ⇒ str(hằng) (lượt 4, F2d); còn lại không chứng minh được ⇒ \"{}\".\"\"\"\n    if isinstance(v, ast.Constant):\n        return v.value\n    if (isinstance(v, ast.FormattedValue) and isinstance(v.value, ast.Constant) and v.conversion == -1\n            and v.format_spec is None and isinstance(v.value.value, (str, int, float))):\n        return str(v.value.value)\n    return \"{}\"\n\n\ndef _van_tinh(n):\n    \"\"\"Giá trị chuỗi TĨNH của một biểu thức (không eval): hằng, f-string (phần biến thành \"{}\"), và phép `+` của chúng.\"\"\"\n    if isinstance(n, ast.Constant) and isinstance(n.value, str):\n        return n.value\n    if isinstance(n, ast.JoinedStr):\n        return \"\".join(_phan_f(v) for v in n.values)\n    if isinstance(n, ast.BinOp) and isinstance(n.op, ast.Add):\n        trai, phai = _van_tinh(n.left), _van_tinh(n.right)\n        return trai + phai if None not in (trai, phai) else (phai if trai is None else trai)\n    return None\n\n\ndef _n4_ast(van_ban):\n    \"\"\"Mọi chuỗi Python (kể cả ghép literal và nối `+`) chứa `login --check` phải là một chuỗi cho phép.\"\"\"\n    cay = ast.parse(van_ban)\n    con_cua_f = {id(v) for n in ast.walk(cay) if isinstance(n, ast.JoinedStr) for v in n.values}\n    gap = set()\n    for n in ast.walk(cay):\n        if id(n) in con_cua_f:\n            continue\n        chuoi = _van_tinh(n)\n        if chuoi is not None and \"login --check\" in chuoi and not isinstance(n, ast.BinOp):\n            gap.add(hashlib.sha256(chuoi.encode(\"utf-8\")).hexdigest())\n        elif chuoi is not None and \"login --check\" in chuoi:\n            # phép `+` chỉ được phép nếu một vế của nó đã là chuỗi cho phép (thông báo pull: f-string + ghi chú tuổi)\n            vế = [_van_tinh(n.left), _van_tinh(n.right)]\n            if not any(v and hashlib.sha256(v.encode(\"utf-8\")).hexdigest() in _CHUOI_CHO_PHEP for v in vế):\n                return False\n    return gap == set(_CHUOI_CHO_PHEP)\n\n\n# Câu PHỦ ĐỊNH được phép xuất hiện trong đầu ra (thông báo pull/load); bóc nó ra rồi mới tìm gợi ý dương.\n_PHU_DINH = \"KHÔNG bằng `nlm login --check`\"\n_CANH = \"SENTINEL-COOKIE-wp727\"\n\n\ndef _vi_pham_dau_ra(van_ban, phai_co):\n    \"\"\"Không gợi ý `login --check`, không lộ cookie, có dấu nhánh `phai_co` (thiếu ⇒ nhánh không được đi tới).\"\"\"\n    return (([\"gợi ý login --check\"] if \"login --check\" in van_ban.replace(_PHU_DINH, \"\") else [])\n            + ([\"lộ chuỗi canh cookie\"] if _CANH in van_ban else [])\n            + [f\"thiếu dấu nhánh {d!r}\" for d in phai_co if d not in van_ban])\n\n\n@contextlib.contextmanager\ndef _home_tam():\n    import tempfile\n    with tempfile.TemporaryDirectory() as d, mock.patch.dict(os.environ, {\"HOME\": d, \"USERPROFILE\": d}):\n        yield d\n\n\ndef _nhanh_goi_y(tg):\n    \"\"\"Chạy offline TỪNG nhánh gợi ý WP727 sửa (blob token giả, HOME tạm, không mạng) ⇒ [(tên, văn bản, dấu nhánh)].\"\"\"\n    import importlib\n    import json\n    store = tg._imp(\"gws_cred_store\")\n    jar = {\"auth.json\": _CANH, \"profiles/default/cookies.json\": \"[]\"}\n    tok = \"offline-test-token\"\n    blob = store.encrypt(json.dumps(jar).encode(\"utf-8\"), tok)\n    nlm_ops = importlib.import_module(\"tl_core.nlm_ops\")\n    rot = lambda *a, **k: {\"found\": True, \"expired\": True, \"name\": \"__Secure-OFFLINE\", \"expires_in_min\": -5.0}\n    kq = [(\"tuoi-cookie\", tg._nlm_cookie_age_note(20.0), (\"NGÀY tuổi\", \"pwsh -NoProfile -File scripts/nlm-credential-refresh.ps1 -ConfigPath\"))]\n    kq.append((\"load-thieu-fid\", tg._nlm_auth_load(tok, \"\")[1], (\"NLM_CRED_FILEID\", \"canary\")))\n    with _home_tam(), _va(tg, _public_curl_bytes=lambda *a, **k: blob, _nlm_auth_files_raw=lambda: {},\n                          _nlm_auth_load_downgrade=lambda *a: (True, \"OFFLINE-cu-hon\")):\n        kq.append((\"load-ha-cap\", tg._nlm_auth_load(tok, \"OFFLINE\")[1], (\"HẠ CẤP\", \"pwsh -NoProfile -File scripts/nlm-credential-refresh.ps1 -ConfigPath\")))\n    with _home_tam(), _va(tg, _public_curl_bytes=lambda *a, **k: blob, _nlm_auth_files_raw=lambda: {},\n                          _nlm_auth_load_downgrade=lambda *a: (False, \"\"), _nlm_auth_age_days=lambda _n: 20.0), \\\n            _va(nlm_ops, _nlm_rotation_token_state=rot):\n        kq.append((\"load-xoay-het-han\", tg._nlm_auth_load(tok, \"OFFLINE\")[1],\n                   (\"BUNDLE_ROTATION_TOKEN_EXPIRED\", \"NGÀY tuổi\", \"pwsh -NoProfile -File scripts/nlm-credential-refresh.ps1 -ConfigPath\")))\n    ra = io.StringIO()\n    ns = argparse.Namespace(config=None, profile=None, cred_file_id=\"OFFLINE\", force=False)\n    with _va(tg, load_creds=lambda *a, **k: None, _nlm_auth_load=lambda *a, **k: (True, \"OFFLINE-msg\")), \\\n            contextlib.redirect_stdout(ra), contextlib.redirect_stderr(ra):\n        tg.cmd_nlm_auth_load(ns)\n    kq.append((\"lenh-load\", ra.getvalue(), (\"[nlm-auth-load] ✓\", \"nlm-auth-status\")))\n    goi = store.encrypt(json.dumps({\"nlm_auth\": jar}).encode(\"utf-8\"), \"offline-master\")\n    ra = io.StringIO()\n    ns = argparse.Namespace(config=None, profile=None, secrets_id=\"OFFLINE\", env=None)\n    with _home_tam(), _va(tg, _master_key=lambda: \"offline-master\", load_creds=lambda *a, **k: None,\n                          _secrets_fetch=lambda *a, **k: (goi, \"OFFLINE\"), _nlm_auth_age_days=lambda _n: 20.0), \\\n            _va(nlm_ops, _nlm_rotation_token_state=lambda *a, **k: {\"found\": False}), \\\n            contextlib.redirect_stdout(ra), contextlib.redirect_stderr(ra):\n        tg.cmd_nlm_auth_pull(ns)\n    kq.append((\"lenh-pull\", ra.getvalue(), (\"[nlm-auth-pull] ✓\", \"NGÀY tuổi\", \"nlm-auth-status\")))\n    return kq\n\n\ndef _n5(tg):\n    nhanh = _nhanh_goi_y(tg)\n    if any(_vi_pham_dau_ra(van_ban, dau) for _ten, van_ban, dau in nhanh):\n        return False\n    # Phản chứng cho chính bộ kiểm: gợi ý dương kiểu cũ, lộ cookie, hoặc nhánh không được đi tới đều phải bị bắt.\n    return all(_vi_pham_dau_ra(x, d) for x, d in ((\"Kiểm: nlm login --check.\", ()), (\"ok \" + _CANH, ()),\n                                                   (_PHU_DINH + \"; Kiểm: nlm login --check\", ()), (\"\", (\"HẠ CẤP\",))))\n\n\ndef run(tl_module):\n    tg = tl_module._imp(\"tl_gws\")\n    tg.bind(tl_module)      # như tl.build_parser: nạp tên trần (_imp, load_creds…) mà các lệnh stage cần\n    van_ban = Path(tg.__file__).read_text(encoding=\"utf-8\")\n    phan_chung_dong = (van_ban + \"    print('Kiểm: nlm login --check')\\n\",        # dòng kiểu cũ\n                       van_ban.replace(\"[nguồn {src}]. Kiểm bằng probe\",           # chen vào CHÍNH dòng được phép\n                                       \"[nguồn {src}]. Kiểm: nlm login --check. Kiểm bằng probe\", 1))\n    phan_chung_ast = (van_ban + '\\nprint(\"Kiểm: nlm \" \"login --check\")\\n',         # hai literal liền nhau (F2b)\n                      van_ban + '\\nprint(f\"x{1}\" + \" Kiểm: nlm log\" + \"in --check\")\\n',   # nối `+` (lượt 3, F2c)\n                      van_ban + \"\\nx = f\\\"Kiểm: nlm {'login'} --check\\\"\\n\")             # `{hằng}` (lượt 4, F2d)\n    goi = van_ban.count(\"_refresh_nlm_auth()\") - 1   # trừ dòng `def`; MỌI người gọi phải dừng khi refresh quá hạn\n    return (goi == 3 == van_ban.count(\"_refresh_nlm_auth() is None\") and _n4(van_ban) and not any(map(_n4, phan_chung_dong)) and _n4_ast(van_ban)\n            and not any(map(_n4_ast, phan_chung_ast)) and _n1_n3(tg) and _n2(tg) and _n5(tg))\n"),
    ("wp88_worktree_recovery.py", "# -*- coding: utf-8 -*-\n\"\"\"Positive recovery evidence for wp88 rows 1, 46, and 90.\"\"\"\n\nTEST_ID = \"wp88_worktree_recovery\"\n\n\ndef run(tl_module):\n    import hashlib\n    import importlib\n    import os\n    from pathlib import Path\n    import subprocess\n    import tempfile\n\n    root = Path(__file__).resolve().parents[2]\n    expected_docs = {\n        \"docs/research/2026-08-04-kiem-chung-auth-fail-close-codex-claude.md\":\n            \"9db028636b77d6e93c82ccc27ddcec12cb9e8c9d51b4f0f0691313697e1b969d\",\n        \"docs/research/2026-08-04-kiem-chung-phuong-an-subscription-codex-claude.md\":\n            \"90bc4509ee829157bae5612c6c470c1369a700ad9b98ef1841eefe89ca559f6f\",\n        \"docs/research/2026-08-04-lua-chon-orchestrator-da-model-codex-claude.md\":\n            \"0d92c0ba751e54be1357a9709ee4bff7463086290e229b1f837c99675a2a7eec\",\n        \"docs/research/2026-08-04-so-sanh-gh-aw-bernstein-agent-orchestrator-metaswarm.md\":\n            \"9c1a3bd4bf826991d8a220f1356b940bdc13fa8db0f88df7c474f1273b70062b\",\n        \"docs/research/2026-08-05-kiem-chung-claude-bare-va-auth-gate.md\":\n            \"d782436174b01e3dc5843a335cf6e2539107f9ef4c2c0c10a21371b8cfdc5d22\",\n    }\n    present_docs = [rel for rel in expected_docs if (root / rel).is_file()]\n    if present_docs and len(present_docs) != len(expected_docs):\n        return False\n    if any(hashlib.sha256((root / rel).read_bytes()).hexdigest() != expected_docs[rel]\n           for rel in present_docs):\n        return False\n\n    loader = importlib.import_module(\"tl_core.test_fragments\")\n    source_ids = set(loader.discover_harness_test_ids(root / \"scripts\" / \"tl_selftest.py\"))\n    superseded_ids = {\n        \"wp41_fragment_loader_zero\",\n        \"wp41_fragment_loader_one\",\n        \"wp41_fragment_loader_many_deterministic\",\n        \"wp41_fragment_duplicate_path_rejected\",\n        \"wp41_fragment_duplicate_wp_id_rejected\",\n        \"wp41_fragment_grandfather_exact_only\",\n        \"wp41_fragment_malformed_contract_rejected\",\n        \"wp41_fragment_syntax_error_diagnosable\",\n        \"wp41_fragment_import_error_diagnosable\",\n        \"wp41_fragment_path_traversal_rejected\",\n        \"wp41_fragment_invalid_path_rejected\",\n        \"wp41_fragment_path_id_mismatch_rejected\",\n        \"wp41_fragment_cwd_independent\",\n        \"wp41_fragment_discovery_adapter\",\n        \"wp41_fragment_read_error_diagnosable\",\n    }\n    if not superseded_ids.issubset(source_ids):\n        return False\n\n    with tempfile.TemporaryDirectory() as tmp:\n        fragment_root = Path(tmp)\n        for test_id in (\"wp88_loader_zulu\", \"wp88_loader_alpha\"):\n            (fragment_root / f\"{test_id}.py\").write_text(\n                f'TEST_ID = \"{test_id}\"\\n\\ndef run(tl_module):\\n    return True\\n',\n                encoding=\"utf-8\", newline=\"\\n\")\n        cases = loader.load_fragment_cases(fragment_root)\n        if ([case.test_id for case in cases]\n                != [\"wp88_loader_alpha\", \"wp88_loader_zulu\"]):\n            return False\n        if not all(case.run(tl_module) for case in cases):\n            return False\n\n    with tempfile.TemporaryDirectory() as tmp:\n        parent = Path(tmp)\n        physical_root = parent / \"physical\"\n        linked_root = parent / \"linked\"\n        physical_root.mkdir()\n        if os.name == \"nt\":\n            made = subprocess.run(\n                [os.environ.get(\"COMSPEC\", \"cmd.exe\"), \"/d\", \"/c\", \"mklink\", \"/J\",\n                 str(linked_root), str(physical_root)],\n                capture_output=True, text=True, encoding=\"utf-8\", errors=\"replace\")\n            if made.returncode != 0:\n                return False\n        else:\n            try:\n                linked_root.symlink_to(physical_root, target_is_directory=True)\n            except OSError:\n                return False\n        try:\n            target = linked_root / \"wp88_read_error.py\"\n            target.write_text(\n                'TEST_ID = \"wp88_read_error\"\\n\\ndef run(tl_module):\\n    return True\\n',\n                encoding=\"utf-8\", newline=\"\\n\")\n            if target == target.resolve(strict=True):\n                return False\n            original_read_text = Path.read_text\n\n            def blocked_read_text(path, *args, **kwargs):\n                if path.name == \"wp88_read_error.py\":\n                    raise OSError(\"wp88 fixture read blocked\")\n                return original_read_text(path, *args, **kwargs)\n\n            Path.read_text = blocked_read_text\n            try:\n                try:\n                    loader.load_fragment_cases(linked_root)\n                except loader.FragmentError as exc:\n                    read_error_ok = exc.code == \"FRAGMENT_READ\"\n                else:\n                    read_error_ok = False\n            finally:\n                Path.read_text = original_read_text\n        finally:\n            if os.name == \"nt\":\n                linked_root.rmdir()\n            else:\n                linked_root.unlink()\n    return read_error_ok\n"),
